pa, pb, pab = df["yogurt"].mean(), df["whole milk"].mean(), (df["yogurt"] & df["whole milk"]).mean()
conf = pab / pa
metricas_mano = {
    "confianza": conf, "lift": pab / (pa * pb), "lift máximo": 1 / max(pa, pb),
    "lift relativo": (pab / (pa * pb)) * max(pa, pb), "leverage": pab - pa * pb,
    "conviction": (1 - pb) / (1 - conf),
    "zhang": (pab - pa * pb) / max(pab * (1 - pa), pa * (pb - pab)),
}
pd.Series(metricas_mano).round(4)
```

