<script>
(() => {
  const K = window.LabKit, root = document.getElementById('mx-lab');
  const $ = s => root.querySelector(s);
  const PRESETS = { yog: [0.28, 0.52, 0.16], freq: [0.5, 0.5, 0.45], rare: [0.05, 0.05, 0.0045] };
  const set = ([a, b, ab]) => { $('#mx-pa').value = a; $('#mx-pb').value = b; bounds(); $('#mx-pab').value = ab; };
  K.segmented($('#mx-preset'), v => { set(PRESETS[v]); render(); });

  const metrics = (pa, pb, pab) => {
    const conf = pab / pa, lift = pab / (pa * pb), lmax = 1 / Math.max(pa, pb), lev = pab - pa * pb;
    const den = Math.max(pab * (1 - pa), pa * (pb - pab));
    return { conf, lift, lmax, lrel: lift / lmax, lev, conv: conf >= 1 - 1e-12 ? Infinity : (1 - pb) / (1 - conf), z: den > 0 ? lev / den : NaN };
  };
  function bounds() {
    const pa = +$('#mx-pa').value, pb = +$('#mx-pb').value, s = $('#mx-pab');
    const lo = Math.max(0, pa + pb - 1), hi = Math.min(pa, pb);
    s.min = lo; s.max = hi; s.value = K.clamp(+s.value, lo, hi);
    return [lo, hi];
  }
  function render() {
    const [lo, hi] = bounds();
    const pa = +$('#mx-pa').value, pb = +$('#mx-pb').value, pab = +$('#mx-pab').value;
