    $('#mx-pb-v').textContent = K.fmt(pb, 2);
    $('#mx-pab-v').textContent = `${K.fmt(pab, 4)} (independencia: ${K.fmt(pa * pb, 4)})`;
    const m = metrics(pa, pb, pab);
    const xs = Array.from({ length: 81 }, (_, i) => lo + (hi - lo) * i / 80);

    const ymax = m.lmax * 1.12;
    let c = K.chart($('#mx-lift'), { width: 380, height: 240, x: [lo, hi], y: [0, ymax], margin: { left: 42, bottom: 40 } });
    c.axes({ xTicks: 4, yTicks: 5, xLabel: 'P(A ∪ B)', yLabel: 'lift', xFmt: v => K.fmt(v, hi < 0.1 ? 3 : 2), yFmt: v => K.fmt(v, ymax < 5 ? 1 : 0) });
    c.line(lo, m.lmax, hi, m.lmax, 's5 line dash thin');
    c.text(lo, m.lmax, `techo = ${K.fmt(m.lmax, 2)}`, { dx: 4, dy: -5, class: 's5' });
    if (1 < ymax) c.line(lo, 1, hi, 1, 'muted line dash thin');
    c.path(xs.map(x => [x, x / (pa * pb)]), 's1 line');
    c.dot(pab, m.lift, 6, 's2 dot');

    c = K.chart($('#mx-norm'), { width: 380, height: 240, x: [lo, hi], y: [-1, 1], margin: { left: 42, bottom: 40 } });
    c.axes({ xTicks: 4, yTicks: 4, xLabel: 'P(A ∪ B)', yLabel: 'valor', xFmt: v => K.fmt(v, hi < 0.1 ? 3 : 2), yFmt: v => K.fmt(v, 1) });
    c.zeroLines();
    c.path(xs.map(x => [x, metrics(pa, pb, x).z]), 's4 line');
    c.path(xs.map(x => [x, metrics(pa, pb, x).lrel]), 's3 line');
    if (Number.isFinite(m.z)) c.dot(pab, m.z, 6, 's4 dot');
    c.dot(pab, m.lrel, 6, 's3 dot');

    $('#mx-conf').textContent = K.fmt(m.conf, 3);
    $('#mx-l').textContent = K.fmt(m.lift, 3);
    $('#mx-lr').textContent = K.fmt(m.lrel, 3);
    $('#mx-lev').textContent = K.fmt(m.lev, 4);
    $('#mx-conv').textContent = Number.isFinite(m.conv) ? K.fmt(m.conv, 3) : '∞';
    $('#mx-z').textContent = K.fmt(m.z, 3);

    const note = $('#mx-note');
    note.className = m.lift > 1.05 ? (m.lrel >= 0.5 ? 'plab-note good' : 'plab-note warn') : 'plab-note';
    note.textContent = m.lift <= 1.05
